async def act(page):
    import asyncio
    import urllib.parse

    # Use the KB helper that is directly suited to locate an article by title on the homepage.
    # Utility: monitor_keyword_and_notify(page, ...) scans the homepage (it calls page.goto('/')) and
    # returns matched article title/url pairs. This is the most appropriate KB function for locating
    # the "JavaScript SpeechSynthesis API" post without reimplementing homepage scraping.
    keyword = "JavaScript SpeechSynthesis API"

    try:
        results = await monitor_keyword_and_notify(page, keyword, check_interval_minutes=60, notify_via="email", max_results=10)
    except Exception:
        results = []

    post_href = None
    if results:
        first = results[0]
        if isinstance(first, dict):
            post_href = first.get("url")

    # Fallback: if the KB helper did not return a usable href, perform a pragmatic site search
    # by navigating to a simple search URL and scanning visible links. We considered the KB helper
    # create_curated_collection_by_search, but it requires a visible search widget in a complementary
    # region and always navigates to '/', so a direct search URL is a pragmatic fallback here.
    if not post_href:
        q = urllib.parse.quote(keyword)
        search_path = f"/?s={q}"
        await page.goto(search_path)
        try:
            await page.wait_for_load_state("networkidle", timeout=3000)
        except Exception:
            pass

        # Look for a link whose visible text contains the keyword
        links = page.get_by_role("link")
        try:
            link_count = await links.count()
        except Exception:
            link_count = 0

        for i in range(link_count):
            l = links.nth(i)
            try:
                txt = (await l.inner_text()).strip().lower()
            except Exception:
                txt = ""
            if keyword.lower() in txt or "javascript speechsynthesis api" in txt:
                try:
                    href = await l.get_attribute("href")
                except Exception:
                    href = None
                if href:
                    post_href = href
                    break

    if not post_href:
        # If still not found, abort so caller is aware the task cannot be completed.
        raise RuntimeError("Could not locate the 'JavaScript SpeechSynthesis API' post on the site.")

    # Resolve the href and prefer a relative goto when same-origin.
    resolved = urllib.parse.urljoin(page.url, post_href)
    parsed_resolved = urllib.parse.urlparse(resolved)
    parsed_current = urllib.parse.urlparse(page.url)

    if parsed_resolved.netloc == parsed_current.netloc or parsed_resolved.netloc == "":
        target = urllib.parse.urlunparse(("", "", parsed_resolved.path, parsed_resolved.params, parsed_resolved.query, parsed_resolved.fragment))
        if not target:
            target = "/"
    else:
        target = resolved

    # Navigate to the post page (goto is used instead of clicking a link). This navigation is necessary
    # to access the comment form and is performed before interacting with comment fields.
    await page.goto(target)
    try:
        await page.wait_for_load_state("networkidle", timeout=5000)
    except Exception:
        # tolerate client-side rendered pages
        pass

    # Locate comment textbox using accessibility-role-centric selectors.
    tboxes = page.get_by_role("textbox")
    try:
        tcount = await tboxes.count()
    except Exception:
        tcount = 0

    comment_locator = None
    comment_meta = {"id": "", "name": ""}

    for i in range(tcount):
        loc = tboxes.nth(i)
        try:
            info = await loc.evaluate(
                "el => ({tag: el.tagName.toLowerCase(), id: el.id||'', name: el.name||'', placeholder: el.placeholder||'', aria: el.getAttribute('aria-label')||''})"
            )
        except Exception:
            info = {"tag": "", "id": "", "name": "", "placeholder": "", "aria": ""}

        joined = " ".join([info.get('id',''), info.get('name',''), info.get('placeholder',''), info.get('aria',''), info.get('tag','')]).lower()
        # Prefer textarea or fields that explicitly reference 'comment'
        if info.get('tag','') == 'textarea' or 'comment' in joined:
            comment_locator = loc
            comment_meta['id'] = info.get('id','')
            comment_meta['name'] = info.get('name','')
            break

    # Fallback heuristic: choose the textbox with the longest helper text (placeholder/aria) or any textarea
    if comment_locator is None and tcount > 0:
        best_idx = None
        best_len = -1
        for i in range(tcount):
            loc = tboxes.nth(i)
            try:
                info = await loc.evaluate("el => ({tag: el.tagName.toLowerCase(), placeholder: el.placeholder||'', aria: el.getAttribute('aria-label')||''})")
            except Exception:
                info = {"tag": "", "placeholder": "", "aria": ""}
            length = len((info.get('placeholder') or "") + (info.get('aria') or ""))
            if info.get('tag','') == 'textarea' or length > best_len:
                best_len = length
                best_idx = i
        if best_idx is not None:
            comment_locator = tboxes.nth(best_idx)
            try:
                info = await comment_locator.evaluate("el => ({tag: el.tagName.toLowerCase(), id: el.id||'', name: el.name||'', placeholder: el.placeholder||'', aria: el.getAttribute('aria-label')||''})")
                comment_meta['id'] = info.get('id','')
                comment_meta['name'] = info.get('name','')
            except Exception:
                comment_meta = {"id": "", "name": ""}

    if comment_locator is None:
        raise RuntimeError("Could not find a comment textbox on the post page using accessibility-role selectors.")

    # Fill the comment exactly as requested.
    await comment_locator.fill("Thanks, this solved my problem.")

    # Optionally attempt to find name and email fields among role=textbox items (skip the comment field)
    name_locator = None
    email_locator = None

    for i in range(tcount):
        loc = tboxes.nth(i)
        try:
            info = await loc.evaluate("el => ({id: el.id||'', name: el.name||'', placeholder: el.placeholder||'', aria: el.getAttribute('aria-label')||'', tag: el.tagName.toLowerCase()})")
        except Exception:
            info = {"id": "", "name": "", "placeholder": "", "aria": "", "tag": ""}

        # Skip the comment field by id or name when possible
        if (comment_meta.get('id') and info.get('id') == comment_meta.get('id')) or (comment_meta.get('name') and info.get('name') == comment_meta.get('name')):
            continue

        joined = " ".join([info.get('id',''), info.get('name',''), info.get('placeholder',''), info.get('aria',''), info.get('tag','')]).lower()
        if name_locator is None and ("name" in joined or "author" in joined):
            if info.get('tag','') != 'textarea' and 'comment' not in joined:
                name_locator = loc
        if email_locator is None and ("email" in joined or "e-mail" in joined):
            email_locator = loc
        if name_locator is not None and email_locator is not None:
            break

    if name_locator is not None:
        try:
            await name_locator.fill("Automation Tester")
        except Exception:
            pass
    if email_locator is not None:
        try:
            await email_locator.fill("tester@example.com")
        except Exception:
            pass

    # Find and click a submit/post-comment button using accessibility role and visible-text heuristics.
    btns = page.get_by_role("button")
    try:
        btn_count = await btns.count()
    except Exception:
        btn_count = 0

    submit_clicked = False
    preferred_keywords = ("post comment", "post", "submit", "send comment", "submit comment", "leave a reply", "comment")

    for i in range(btn_count):
        b = btns.nth(i)
        try:
            txt = (await b.inner_text()).strip().lower()
        except Exception:
            txt = ""
        if any(k in txt for k in preferred_keywords):
            try:
                await b.click()
                submit_clicked = True
                break
            except Exception:
                pass

    if not submit_clicked and btn_count > 0:
        try:
            await btns.first.click()
            submit_clicked = True
        except Exception:
            pass

    # Allow a short moment for submission processing. Clicking the submit button is the final action.
    await asyncio.sleep(2)

    return

